mapper.update:
UPDATE orders
SET
    price = #{updatedPrice}
WHERE order_id = #{orderId}

UPDATE orders
SET
    order_status = #{orderStatus}
WHERE order_id = #{orderId}

mapper.select:
SELECT
    order_id
FROM orders
WHERE store_id = #{storeId}
AND DATE_FORMAT(ordered_at, '%Y-%m-%d') = #{currentTime}
AND order_status = 'UNPAID'
